-- No Registry duplication, question publication UPDATE, Evidence review promotion, seed or billing mutation.
-- Apply only after the separate coaching/disclosure/continuation candidate and deployment preflight.
begin;
set local lock_timeout='5s';set local statement_timeout='180s';
select pg_advisory_xact_lock(hashtextextended('legendstudy-release57-scope',71658));
