 select md5(pg_get_functiondef(p.oid)) hash,pg_get_userbyid(p.proowner) owner,p.proacl::text acl,to_jsonb(p.proconfig) config into a from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname=e->>'nspname' and p.proname=e->>'proname' and pg_get_function_identity_arguments(p.oid)=e->>'args';
