 if (select jsonb_agg(value->'question_id' order by value->>'question_id') from jsonb_array_elements(package->'questions'))
  is distinct from (select jsonb_agg(value order by value::text) from jsonb_array_elements(e->'questionIds')) then raise exception 'RELEASE57_PACKAGE_QUESTION_SET_DRIFT: %',e->>'examId';end if;
 for leaf in select key,value from jsonb_each_text(e->'mathQuestions') loop
  if not exists(select 1 from public.math_subproblems l join public.math_problems p on p.id=l.problem_id join public.math_problem_sets s on s.id=p.problem_set_id join public.essay_questions q on q.id=l.essay_question_id and q.essay_exam_id=s.essay_exam_id
   where l.id=leaf.value::uuid and q.id=leaf.key::uuid and s.essay_exam_id=(e->>'examId')::uuid and p.state='ACTIVE' and s.state='ACTIVE') then raise exception 'RELEASE57_CANONICAL_MAPPING_DRIFT: %',leaf.value;end if;
 end loop;
 end loop;
 if not exists(select 1 from public.math_subproblems l join public.math_problems p on p.id=l.problem_id join public.math_problem_sets s on s.id=p.problem_set_id
 join public.essay_questions q on q.id='cea40cf3-dc05-507a-a6eb-fd5e1e1847bb'::uuid and q.essay_exam_id=s.essay_exam_id
 where l.id='3bab07d3-c047-53c2-89ad-9fa20ec7b3f3'::uuid and p.state='ACTIVE' and s.state='ACTIVE') then raise exception 'RELEASE57_LEGACY_MAPPING_DRIFT';end if;
end $guard$;
-- RELEASE57_SCOPE_AFTER_GUARDS
-- Internal exact release catalog. Submission membership never depends on a UI row limit.
create function math_private.release_catalog(p_exam uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare result jsonb;begin
 select coalesce(jsonb_agg(x),'[]') into result from (
 select s.essay_exam_id,q.id as essay_question_id,l.id as leaf_id,l.statement,p.statement as problem_statement,s.label||' · '||q.label as label,l.response_format
 from public.math_subproblems l join public.math_problems p on p.id=l.problem_id join public.math_problem_sets s on s.id=p.problem_set_id
 join public.essay_questions q on q.id=case when l.id='3bab07d3-c047-53c2-89ad-9fa20ec7b3f3'::uuid then 'cea40cf3-dc05-507a-a6eb-fd5e1e1847bb'::uuid else l.essay_question_id end and q.essay_exam_id=s.essay_exam_id
 where l.id=any(array['018b6b54-4815-504a-adb8-685faa204516'::uuid,'06cd2ae1-c7a5-52cb-8ab9-2725bbc7af9f'::uuid,'0afcc1e0-68ed-56f1-94ef-52d4d81f144b'::uuid,'148cb335-4931-52c1-8270-a1bac78c7082'::uuid,'1699c649-dcf0-5024-84f3-4775eaed49c3'::uuid,'169e0ff4-4fd3-5f87-9908-a8cbe7e768ce'::uuid,'1cd8b541-a44c-513c-9afe-39cd46664a69'::uuid,'1ffa56cf-7b97-592b-a48c-8ab19e1e29f0'::uuid,'201f3df4-4851-52a3-9e18-6209ef34b56c'::uuid,'206c7e42-f324-5d92-8bbe-b11979d57eda'::uuid,'20fb9238-14bb-5100-949f-66dba3f08ccc'::uuid,'2186939f-a84c-535e-bd6b-647713856dbe'::uuid,'24f4aa41-fdc1-5801-ac60-fe7b1c4ded0c'::uuid,'2b528dc2-5c4e-5e4f-8ecb-8bb4c2a4d8e1'::uuid,'2c34ec6b-5821-56df-b07c-99d5f365eca4'::uuid,'2c34f7fb-1485-5030-9b71-b2bd72fd6403'::uuid,'2c405a4c-6a94-530d-be82-76ecf8158138'::uuid,'2ce0c120-41de-538e-aed7-376b7efc5f3b'::uuid,'301f18a3-73b7-5552-a960-6235ff53b1fc'::uuid,'31a6ae05-81d5-5026-907b-85f75f2bec6d'::uuid,'31df8d5d-a638-50dd-b6f1-4b3ed6da4610'::uuid,'36497aa6-43a3-50e2-b069-26c45566b086'::uuid,'37db2b14-b863-561e-87dc-df8e286746ca'::uuid,'3bab07d3-c047-53c2-89ad-9fa20ec7b3f3'::uuid,'3e5189bc-840a-54ee-a6ab-d261261c5413'::uuid,'43f13de2-e1f7-564b-a572-90e6f2431d37'::uuid,'502352a4-3b67-58f8-81bf-70c0271fc6c6'::uuid,'591f4939-0db3-565e-9ab0-d1ae60f438e6'::uuid,'609040a7-cee3-55b9-a678-2714f335a7a1'::uuid,'663a25a2-10bb-5f49-b4b0-69a6a5759580'::uuid,'674d75b3-7850-5487-bf75-3c9603f58f7f'::uuid,'67980cc4-1ff2-5e99-b482-7b1c913918c5'::uuid,'687452a8-0e06-5a41-bd5c-6850364d5e02'::uuid,'69b117c5-2fea-5eaa-9c25-d812f1d1b718'::uuid,'6dd62ff5-b153-5dea-aeca-4bb7b86bbb2b'::uuid,'6f5aa167-60ed-5b13-a88f-5bf332b8705b'::uuid,'73a0a0e0-ad1e-52cd-bf3d-ba3dc5773ded'::uuid,'7532956e-9fb5-57c1-98a3-f71aeee46941'::uuid,'7b3d8849-dc6b-5613-9de2-585fff227ab5'::uuid,'7d26749d-106d-535d-90c1-1c1bdebf8771'::uuid,'8000aa8a-902c-51da-b8c9-3b02b2b6e766'::uuid,'81a39ee1-28b2-5c3f-8a89-a96745045400'::uuid,'81f6f465-d368-55c3-9245-1e162c6a4170'::uuid,'838b227c-a442-5088-be0a-3339e0419d3f'::uuid,'8d288993-9218-5b8c-95a9-581adf4d6e03'::uuid,'9464a798-36f8-5211-bcfb-c8ad43c1b4ad'::uuid,'9765f9ca-2f33-58bb-8e97-c7575564ad58'::uuid,'97db9255-d3c9-55c9-8af4-082133a65ee4'::uuid,'9c4f66ce-893a-566c-8883-17838de68ae5'::uuid,'a066dde9-1311-5b54-82d0-032094087dda'::uuid,'a655a974-324b-507d-bc59-fc6c86e35d78'::uuid,'a716fd23-217a-5383-bab0-3e21271517b8'::uuid,'ae5f2aff-f6f9-5da3-bd48-db41539858b3'::uuid,'af397781-3e8d-5cc5-9018-ae665ae81d49'::uuid,'bb365a98-0f32-5ff7-8ee6-bf5f8534f2a2'::uuid,'be56b9db-a783-5db8-8b0e-810a57473bc8'::uuid,'c0247ec7-5e2f-5d84-ba81-691a5a0bea84'::uuid,'c16c7ced-07e9-585a-9cea-a424c9fe6fd2'::uuid,'c3abc2aa-8610-52bc-be22-bdebff5b2911'::uuid,'cca96260-ac54-52d2-83dd-008a0429200e'::uuid,'d3fa91a9-315c-52cf-86b9-e4e3ad1f7aca'::uuid,'df0b03d7-613b-5926-a380-df9a5eea74dc'::uuid,'e0f71b73-0f94-5fdc-94f6-6980d3a0bdb2'::uuid,'e7379b0d-6b85-564f-9118-29cbdde8e3f4'::uuid,'e82980f0-57a7-5e52-b267-92742323d8d0'::uuid,'ec11c069-b10c-5e16-89c8-0e20060fcfa3'::uuid,'ef007231-0962-5c3e-ace9-1fc3593cf5f5'::uuid,'efca55c7-550a-55be-8d62-c0a4c738b545'::uuid,'f43a377a-034e-5a7c-9b9f-dd1e60b16afa'::uuid,'f5860380-dcdb-553e-befd-7b23a326fbef'::uuid,'f64947cb-345f-516c-823c-38d120124d6d'::uuid,'fa912822-b549-503b-b3ee-7b96a9116183'::uuid]) and p.state='ACTIVE' and s.state='ACTIVE' and (p_exam is null or s.essay_exam_id=p_exam)
 order by s.id,p.display_order,l.display_order,l.id) x;
 if jsonb_array_length(result)>512 then raise program_limit_exceeded using message='RELEASE_CATALOG_LIMIT_EXCEEDED';end if;
 return result;
end$$;
revoke all on function math_private.release_catalog(uuid) from public,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.math_catalog(p_limit integer DEFAULT 20)
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$
declare result jsonb;begin
 perform math_private.require_active(array[auth.uid()]);
 if p_limit is null or p_limit not between 1 and 512 then raise invalid_parameter_value;end if;
 result=math_private.release_catalog(null);
 -- Fixed APP58 requests 50 with no paging. Preserve its JSON-array shape and all approved items.
 -- Existing smaller limits keep their strict semantics. No arbitrary Registry rows are exposed.
 if p_limit=50 then return result;end if;
 return (select coalesce(jsonb_agg(value order by ordinality),'[]') from jsonb_array_elements(result) with ordinality where ordinality<=p_limit);
end$function$;
