 raise exception 'MATH_EVALUATIONS_PAUSED' using errcode='55000';end if;
 if new.leaf_id is null or not (new.leaf_id=any(array['018b6b54-4815-504a-adb8-685faa204516'::uuid,'06cd2ae1-c7a5-52cb-8ab9-2725bbc7af9f'::uuid,'0afcc1e0-68ed-56f1-94ef-52d4d81f144b'::uuid,'148cb335-4931-52c1-8270-a1bac78c7082'::uuid,'1699c649-dcf0-5024-84f3-4775eaed49c3'::uuid,'169e0ff4-4fd3-5f87-9908-a8cbe7e768ce'::uuid,'1cd8b541-a44c-513c-9afe-39cd46664a69'::uuid,'1ffa56cf-7b97-592b-a48c-8ab19e1e29f0'::uuid,'201f3df4-4851-52a3-9e18-6209ef34b56c'::uuid,'206c7e42-f324-5d92-8bbe-b11979d57eda'::uuid,'20fb9238-14bb-5100-949f-66dba3f08ccc'::uuid,'2186939f-a84c-535e-bd6b-647713856dbe'::uuid,'24f4aa41-fdc1-5801-ac60-fe7b1c4ded0c'::uuid,'2b528dc2-5c4e-5e4f-8ecb-8bb4c2a4d8e1'::uuid,'2c34ec6b-5821-56df-b07c-99d5f365eca4'::uuid,'2c34f7fb-1485-5030-9b71-b2bd72fd6403'::uuid,'2c405a4c-6a94-530d-be82-76ecf8158138'::uuid,'2ce0c120-41de-538e-aed7-376b7efc5f3b'::uuid,'301f18a3-73b7-5552-a960-6235ff53b1fc'::uuid,'31a6ae05-81d5-5026-907b-85f75f2bec6d'::uuid,'31df8d5d-a638-50dd-b6f1-4b3ed6da4610'::uuid,'36497aa6-43a3-50e2-b069-26c45566b086'::uuid,'37db2b14-b863-561e-87dc-df8e286746ca'::uuid,'3bab07d3-c047-53c2-89ad-9fa20ec7b3f3'::uuid,'3e5189bc-840a-54ee-a6ab-d261261c5413'::uuid,'43f13de2-e1f7-564b-a572-90e6f2431d37'::uuid,'502352a4-3b67-58f8-81bf-70c0271fc6c6'::uuid,'591f4939-0db3-565e-9ab0-d1ae60f438e6'::uuid,'609040a7-cee3-55b9-a678-2714f335a7a1'::uuid,'663a25a2-10bb-5f49-b4b0-69a6a5759580'::uuid,'674d75b3-7850-5487-bf75-3c9603f58f7f'::uuid,'67980cc4-1ff2-5e99-b482-7b1c913918c5'::uuid,'687452a8-0e06-5a41-bd5c-6850364d5e02'::uuid,'69b117c5-2fea-5eaa-9c25-d812f1d1b718'::uuid,'6dd62ff5-b153-5dea-aeca-4bb7b86bbb2b'::uuid,'6f5aa167-60ed-5b13-a88f-5bf332b8705b'::uuid,'73a0a0e0-ad1e-52cd-bf3d-ba3dc5773ded'::uuid,'7532956e-9fb5-57c1-98a3-f71aeee46941'::uuid,'7b3d8849-dc6b-5613-9de2-585fff227ab5'::uuid,'7d26749d-106d-535d-90c1-1c1bdebf8771'::uuid,'8000aa8a-902c-51da-b8c9-3b02b2b6e766'::uuid,'81a39ee1-28b2-5c3f-8a89-a96745045400'::uuid,'81f6f465-d368-55c3-9245-1e162c6a4170'::uuid,'838b227c-a