;
-- RELEASE57_SCOPE_AFTER_FUNCTIONS
do $post$ begin
 if exists(select 1 from release57_scope_before b join pg_proc p using(oid) where p.proowner<>b.proowner or p.proacl is distinct from b.proacl or p.proconfig is distinct from b.proconfig or p.prosecdef<>b.prosecdef) then raise exception 'RELEASE57_SCOPE_OWNER_ACL_SECURITY_DRIFT';end if;
end $post$;
notify pgrst, 'reload schema';
commit;
